<?php

namespace Database\Seeders;

use App\Models\Puzzle;
use Illuminate\Database\Seeder;

/**
 * Practice puzzles from data/puzzles.json, generated by
 * `packages/nard_ai/tool/gen_puzzles.dart` (heuristic self-play, 2-ply best
 * turn clearly ahead of the second best). Idempotent.
 */
class PuzzleSeeder extends Seeder
{
    public function run(): void
    {
        /** @var array<int, array<string, mixed>> $puzzles */
        $puzzles = json_decode((string) file_get_contents(__DIR__.'/data/puzzles.json'), true, flags: JSON_THROW_ON_ERROR);
        foreach ($puzzles as $p) {
            Puzzle::query()->updateOrCreate(['id' => $p['id']], [
                'variant' => $p['variant'],
                'side' => $p['side'],
                'dice' => $p['dice'],
                'board' => $p['board'],
                'solution' => $p['solution'],
                'result_board' => $p['resultBoard'],
                'second_best' => $p['secondBest'] ?? null,
                'rating' => $p['rating'],
                'phase' => $p['phase'],
            ]);
        }
    }
}
